{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for v, g in refinement.items():
        members.setdefault(g, []).append(v)
    for g in members:
        members[g].sort()
    aggregate = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        key = tuple(sorted([gu, gv]))
        aggregate[key] = aggregate.get(key, 0) + w
    aggregate_edges = [list(key) + [weight] for key, weight in sorted(aggregate.items())]
    return {"members": members, "aggregate_edges": aggregate_edges}"}
